(async () => {
  const primary = 'https://testingcf.jsdelivr.net/gh/MagicalAstrogy/MagVarUpdate@d03b7dc8a6ebf9bd611c7e2dc91f3b35462deebc/artifact/bundle.js';
  const fallback = 'https://cdn.jsdelivr.net/gh/MagicalAstrogy/MagVarUpdate@d03b7dc8a6ebf9bd611c7e2dc91f3b35462deebc/artifact/bundle.js';

  try {
    try {
      await import(primary);
    } catch (primaryError) {
      console.warn('[香火成神] MVU 国内主源失败，切换全球备源', primaryError);
      await import(fallback);
    }

    if (typeof waitGlobalInitialized === 'function') {
      await waitGlobalInitialized('Mvu');
    }

    console.info('[香火成神] MVU 国内加载器就绪');
  } catch (error) {
    console.error('[香火成神] MVU 加载失败', error);
    if (window.toastr?.error) {
      window.toastr.error('MVU 运行库加载失败，请检查网络后重载角色卡。', '香火成神系统');
    }
  }
})();

