(async () => {
  'use strict';
  const CONFIG={"protocol":1,"projectId":"xianghuo-cheng-shen","releaseVersion":"0.15.2","repository":"1208496/ling-keke-repository","preferredRepositoryName":"ling-keke-repository","repositoryDescription":"凌keke的仓库 · 香火成神系统配套更新","checkIntervalMs":900000,"maxBytes":2097152};
  const EMBEDDED={"protocol":1,"projectId":"xianghuo-cheng-shen","version":"0.15.2","hudRevision":"bf7d92ab02f8865a341c2089a3be2b198188b778551de6e8288b9d2f2aeb4b56","schemaVersion":"1.8.0","readableSchemas":["1.3.0","1.4.0","1.5.0","1.6.0","1.7.0","1.8.0"],"migrations":[{"from":"1.3.0","to":"1.4.0","operations":[]},{"from":"1.4.0","to":"1.5.0","operations":[]},{"from":"1.5.0","to":"1.6.0","operations":[]},{"from":"1.6.0","to":"1.7.0","operations":[]},{"from":"1.7.0","to":"1.8.0","operations":[]}],"schemaSource":"/* global z, toastr */

const WORLD_KEYS = ['未选择', '异能都市', '古代修仙', '西幻', '跨世界'];
const STAGES = ['泥像期', '石像期', '铜像期', '银像期', '金像期', '玉像期', '宇宙神像期'];
const FAITH_LEVELS = ['普通', '核心', '狂热'];
const TASK_STATES = ['未发布', '进行中', '待验收', '已完成', '已失败', '已替代'];
const TRUTH_STAGES = ['毫无察觉', '隐约熟悉', '主动追索', '确认自身', '创世归位'];

const looseObject = shape => z.object(shape).passthrough();
const objectValue = shape => z.preprocess(
  value => value && typeof value === 'object' && !Array.isArray(value) ? value : {},
  looseObject(shape),
);
const recordValue = (valueSchema, fallback = {}) => z.preprocess(
  value => value && typeof value === 'object' && !Array.isArray(value) ? value : fallback,
  z.record(z.string(), valueSchema),
);
const arrayValue = (valueSchema, fallback = []) => z.preprocess(
  value => Array.isArray(value) ? value : fallback,
  valueSchema,
);
const stringValue = fallback => z.preprocess(
  value => value === undefined || value === null ? fallback : String(value),
  z.string(),
);
const numberValue = fallback => z.preprocess(
  value => value === undefined || value === null || value === '' ? fallback : value,
  z.coerce.number().int().min(0),
);
const boolValue = fallback => z.preprocess(
  value => value === undefined || value === null ? fallback
    : value === 'false' || value === 0 ? false
      : value === 'true' || value === 1 ? true : value,
  z.boolean(),
);
const enumValue = (values, fallback) => z.preprocess(
  value => values.includes(value) ? value : fallback,
  z.enum(values),
);

const TaskSchema = z.preprocess(value => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return value;
  const { 限期分钟, 期限说明, 失败处罚, ...active } = value;
  return active;
}, objectValue({
  id: stringValue(''),
  标题: stringValue(''),
  目标: stringValue(''),
  完成条件: stringValue(''),
  阶段目标: stringValue(''),
  进度当前: numberValue(0),
  进度目标: numberValue(0),
  奖励神力: numberValue(0),
  奖励说明: stringValue(''),
  奖励记忆碎片: stringValue(''),
  状态: enumValue(TASK_STATES, '未发布'),
}));

const WorldStateSchema = objectValue({
  地区声望: stringValue('无名'),
  稳定祭祀点: numberValue(0),
  公开神迹: numberValue(0),
  主要势力关系: recordValue(z.string()),
  首章状态: stringValue('未开始'),
});

const PrivateProfileSchema = objectValue({
  乳房: stringValue('未记录'),
  小穴: stringValue('未记录'),
  后穴: stringValue('未记录'),
});

const LegacyImportantPersonSchema = objectValue({
  姓名: stringValue(''),
  年龄: numberValue(18),
  性别: stringValue(''),
  身份: stringValue(''),
  信仰等级: enumValue(['未确认','未信仰',...FAITH_LEVELS], '未确认'),
  关系: z.preprocess(value => value == null ? '' : value, z.union([z.string(), z.record(z.string(), z.unknown())])),
  所在位置: stringValue(''),
  当前状态: stringValue(''),
  当前服装: stringValue(''),
  当前心理: stringValue(''),
  当前姿势: stringValue(''),
  情绪: stringValue(''),
  外貌: stringValue(''),
  能力: arrayValue(z.array(z.string())),
  成长: objectValue({位阶:stringValue('未确认'),形态:stringValue('未进化'),神赐经历:arrayValue(z.array(z.string()).max(8))}),
  祈愿: objectValue({内容:stringValue(''),轮次:numberValue(0)}),
  与神关系: stringValue(''),
  近期经历: stringValue(''),
  最后更新: stringValue(''),
  别称: arrayValue(z.array(z.string()).max(8)),
  情感关系: objectValue({亲近阶段:enumValue(['未确认','初识','熟悉','倾慕','亲密','伴侣'],'未确认'),公开身份:stringValue('未确认'),当前在意:stringValue('未确认'),关键事实:arrayValue(z.array(objectValue({摘要:stringValue(''),来源楼层:numberValue(0),来源swipe:numberValue(0)})).max(8))}),
  私密档案: PrivateProfileSchema.optional(),
}).superRefine((person, context) => {
  if (person.年龄 < 18) {
    context.addIssue({
      code: 'custom',
      path: ['年龄'],
      message: '重要人物必须年满 18 岁',
    });
  }
});

const ImportantPersonSchema = z.union([
  looseObject({姓名:stringValue(''),信仰等级:enumValue(['未确认','未信仰',...FAITH_LEVELS],'未信仰'),档案版本:z.string().min(1),当前服装:stringValue(''),当前心理:stringValue(''),当前姿势:stringValue(''),当前状态:stringValue(''),情绪:stringValue(''),当前意图:stringValue(''),临时态度:stringValue(''),临时效果:arrayValue(z.array(z.string())),祈愿:objectValue({内容:stringValue(''),轮次:numberValue(0)})}),
  LegacyImportantPersonSchema,
]);

const OrdinaryFollowerSchema = objectValue({
  姓名: stringValue(''),
  年龄: numberValue(18),
  性别: stringValue(''),
  身份: stringValue(''),
  所在地: stringValue(''),
  首次见证: stringValue(''),
}).superRefine((person, context) => {
  if (person.年龄 < 18) {
    context.addIssue({
      code: 'custom',
      path: ['年龄'],
      message: '普通信徒必须年满 18 岁',
    });
  }
});

const CurrentVisitorSchema = objectValue({
  姓名: stringValue(''),
  年龄: numberValue(18),
  性别: stringValue(''),
  自定义描述: stringValue(''),
  身份: stringValue(''),
  状态: stringValue(''),
  所在地: stringValue(''),
}).superRefine((person, context) => {
  if (person.年龄 < 18) {
    context.addIssue({
      code: 'custom',
      path: ['年龄'],
      message: '当前来客必须年满 18 岁',
    });
  }
});

const BuildingSchema = objectValue({
  名称: stringValue(''), 类型: stringValue('房屋'),
  状态: enumValue(['规划','建造中','已完成','损毁'],'规划'),
  x: z.preprocess(v => v === null ? undefined : v, z.coerce.number().finite()), y: z.preprocess(v => v === null ? undefined : v, z.coerce.number().finite()),
  容量: numberValue(0), 安全: boolValue(false), 建造者: arrayValue(z.array(z.string())),
  住户: arrayValue(z.array(z.string())), 说明: stringValue(''),
}).superRefine((b,ctx) => {
  if (b.住户.length > b.容量 || b.住户.length && (b.状态 !== '已完成' || !b.安全) || new Set(b.住户).size !== b.住户.length) ctx.addIssue({code:'custom',path:['住户'],message:'住户须唯一，且建筑完工、安全、容量足够'});
});
const DomainSchema = objectValue({
  建筑: recordValue(BuildingSchema),
  已知地点: arrayValue(z.array(z.string())),
}).superRefine((domain,ctx) => {
  const residents=new Set();
  for (const [id,b] of Object.entries(domain.建筑)) for (const key of b.住户) {
    if (residents.has(key)) ctx.addIssue({code:'custom',path:['建筑',id,'住户'],message:'同一住户不能同时入住两栋建筑'});
    residents.add(key);
  }
});
const ClockSchema=objectValue({
  起始时刻:stringValue('0102-09-16 17:40'),经过分钟:numberValue(0),已初始化:boolValue(false),
  已结算日:numberValue(0),累计香火:numberValue(0),最近批次:stringValue(''),
  结算记录:arrayValue(z.array(objectValue({截止日期:stringValue(''),天数:numberValue(0),日收益:numberValue(0),总额:numberValue(0)})).max(8)),
});
const PositionSchema=objectValue({地点ID:stringValue(''),x:z.coerce.number().finite().default(0),y:z.coerce.number().finite().default(0),有效:boolValue(false)});
const Schema = z.preprocess(root => {
  if (!root || typeof root !== 'object' || Array.isArray(root)) {
    return {};
  }
  return root;
}, looseObject({
  元数据: objectValue({
    schema版本: stringValue('1.8.0'),
    卡片版本: stringValue('0.15.0'),
    开局完成: boolValue(false),
    当前开局: stringValue('未选择'),
    最近更新说明: stringValue(''),
  }),
  世界: objectValue({
    当前世界: enumValue(WORLD_KEYS, '未选择'),
    已解锁世界: arrayValue(z.array(z.enum(WORLD_KEYS)).max(3)),
    当前区域: stringValue(''),
    当前地点: stringValue(''),
    剧情时间: stringValue('未开始'),
    世界状态: recordValue(WorldStateSchema),
  }),
  系统: objectValue({
    人格: stringValue('可靠执事').transform(value => value === '沙雕萝莉' ? '沙雕萌妹' : value),
    当前提示: stringValue('等待开局选择系统人格。'),
  }),
  神格: objectValue({
    神名: stringValue(''),
    神格性别: stringValue(''),
    生前姓名: stringValue(''),
    外貌: stringValue(''),
    生前背景: stringValue(''),
    神像阶段: enumValue(STAGES, '泥像期'),
    绝对领域: objectValue({
      中心: stringValue('初始神像所在处'),
      半径: numberValue(30),
    }),
    神力积分: numberValue(3),
    化身: objectValue({
      可凝聚: boolValue(false),
      状态: stringValue('无实体'),
      所在地: stringValue('神像内'),
    }),
    附身: objectValue({
      进行中: boolValue(false),
      信徒键: stringValue(''),
      开始分钟: numberValue(0),
    }),
    已解锁能力: arrayValue(z.array(z.string()), ['神谕传音', '方寸异象']),
  }),
  信仰: objectValue({
    普通信徒: numberValue(0),
    核心信徒: numberValue(0),
    狂热信徒: numberValue(0),
    上次结算天数: numberValue(1),
    累计公开神迹: numberValue(0),
  }),
  任务: objectValue({
    当前主线: TaskSchema,
    支线: arrayValue(z.array(TaskSchema).max(2)),
    最近完成: stringValue(''),
  }),
  时序:ClockSchema,
  地图定位:objectValue({地区ID:stringValue('qingya'),玩家:PositionSchema,神像:PositionSchema}),
  神域: recordValue(DomainSchema),
  重要人物: recordValue(ImportantPersonSchema),
  信众管理: objectValue({
    轮次:numberValue(0),最近剧情楼层:stringValue(''),置顶序号:numberValue(0),
    自动隐藏轮数:numberValue(12),活跃上限:numberValue(12),
    人物:recordValue(objectValue({模式:enumValue(['自动','隐藏','显示'],'自动'),置顶序号:numberValue(0),最后活跃轮:numberValue(0),最近祈愿轮:z.number().int().min(-1).default(-1)})),
  }),
  信众群体: recordValue(objectValue({名称:stringValue(''),普通:numberValue(0),核心:numberValue(0),狂热:numberValue(0)})),
  普通信徒名录: arrayValue(z.array(OrdinaryFollowerSchema).max(20)),
  真相: objectValue({
    认知阶段: enumValue(TRUTH_STAGES, '毫无察觉'),
    记忆碎片: arrayValue(z.array(z.string())),
    未解线索: arrayValue(z.array(z.string()).max(12)),
  }),
  剧情: objectValue({
    在场人物: arrayValue(z.array(z.string()).max(12)),
    当前篇章: stringValue(''),
    当前危机: stringValue(''),
    当前目标: stringValue(''),
    当前来客: CurrentVisitorSchema,
    待兑现伏笔: arrayValue(z.array(z.string()).max(12)),
    近期摘要: stringValue(''),
  }),
}));

","modules":[{"id":"state-patch-guard","code":"return (async () => {
  'use strict';
  const own = (o,k) => Object.hasOwn(o || {},k);
  const clone = value => JSON.parse(JSON.stringify(value));
  const forbidden = new Set(['__proto__','prototype','constructor','$internal','$meta']);
  const dynamic = new Set(['当前服装','当前心理','当前姿势','当前状态','情绪','当前意图','临时态度','临时效果','祈愿']);
  const checkValue = value => {
    if (value && typeof value === 'object') for (const key of Object.keys(value)) {
      if (forbidden.has(key)) throw Error('变量补丁含受保护字段');
      checkValue(value[key]);
    }
  };
  const parts = path => {
    if (typeof path !== 'string' || !path.startsWith('/') || /~(?![01])/u.test(path)) throw Error('变量补丁路径无效');
    const result = path.slice(1).split('/').map(s=>s.replaceAll('~1','/').replaceAll('~0','~'));
    if (result.some(s=>!s || forbidden.has(s))) throw Error('变量补丁路径受保护');
    return result;
  };
  const commandPath = tokens => tokens.map(s=>`[${JSON.stringify(s)}]`).join('');
  function prepare(data, nativeCommands, message) {
    const blocks = [...String(message).matchAll(/<UpdateVariable>\s*([\s\S]*?)\s*<\/UpdateVariable>/g)];
    if (!blocks.length) { if (/<UpdateVariable>|<JSONPatch>/.test(message)) throw Error('变量更新块未闭合'); return null; }
    if (blocks.length !== 1) throw Error('本轮存在多个变量更新块');
    const body = blocks[0][1].replace(/^<analysis>[\s\S]*?<\/analysis>\s*/,'');
    if (!body.startsWith('<JSONPatch>')) return null; // Preserve native legacy-command handling.
    const raw = body.slice('<JSONPatch>'.length).replace(/<\/JSONPatch>\s*$/,'').trim();
    if (raw.length > 96000) throw Error('变量补丁过长');
    const operations = JSON.parse(raw); // Only a complete JSON array; never infer missing data.
    if (!Array.isArray(operations) || operations.length > 128) throw Error('变量补丁必须是至多128项的数组');
    const archives = new Map();
    for (const block of String(message).matchAll(/<CharacterArchive>\s*([\s\S]*?)\s*<\/CharacterArchive>/g)) {
      const rows = JSON.parse(block[1]);
      if (!Array.isArray(rows) || rows.length > 30) throw Error('人物资料块格式错误');
      for (const row of rows) {
        if (typeof row?.id !== 'string' || !row.id || forbidden.has(row.id) || !row.资料 || Array.isArray(row.资料) || typeof row.资料 !== 'object') throw Error('人物资料格式错误');
        checkValue(row);
        if (archives.has(row.id)) throw Error('人物资料出现重复ID');
        archives.set(row.id,row.资料);
      }
    }
    const commands = [], seeds = {};
    const emit = operation => {
      checkValue(operation);
      if (!['add','replace','remove','move'].includes(operation?.op)) throw Error('不支持的变量补丁操作');
      const tokens = parts(operation.path);
      if (tokens[0] === '重要人物') {
        if (tokens.length < 2) throw Error('禁止整表覆盖人物');
        if (tokens.length === 2 && operation.op !== 'remove') {
          const profile = archives.get(tokens[1]);
          if (!profile) throw Error('整个人物写入缺少独立资料块');
          if (!own(data.重要人物,tokens[1])) {
            if (!Number.isInteger(profile.年龄) || profile.年龄 < 18) throw Error('新人物缺少成年年龄');
            seeds[tokens[1]] = clone(profile);
            delete seeds[tokens[1]].档案版本;
          }
          for (const [key,value] of Object.entries(operation.value || {})) if (dynamic.has(key)) emit({op:'replace',path:operation.path+'/'+key,value});
          return; // The archive writer alone issues immutable revision references.
        }
        if (tokens.length > 2 && !dynamic.has(tokens[2])) throw Error('固定人物资料须通过独立资料块保存');
      }
      if (operation.op === 'move' && parts(operation.from)[0] === '重要人物') throw Error('禁止移动人物档案字段');
      if (['add','replace'].includes(operation.op) && !own(operation,'value')) throw Error('变量补丁缺少value');
      const path = commandPath(tokens);
      const command = {full_match:JSON.stringify(operation),reason:'json_patch'};
      if (operation.op === 'replace') Object.assign(command,{type:'set',args:[path,JSON.stringify(operation.value)]});
      if (operation.op === 'add') Object.assign(command,{type:'insert',args:[commandPath(tokens.slice(0,-1)),/^\d+$/.test(tokens.at(-1)) ? tokens.at(-1) : JSON.stringify(tokens.at(-1)),JSON.stringify(operation.value)]});
      if (operation.op === 'remove') Object.assign(command,{type:'delete',args:[path]});
      if (operation.op === 'move') Object.assign(command,{type:'move',args:[commandPath(parts(operation.from)),path]});
      commands.push(command);
    };
    operations.forEach(emit);
    // New archive-only people must exist before same-turn dynamic set commands execute.
    for (const [id,profile] of archives) if (!own(data.重要人物,id) && !own(seeds,id)) {
      if (!Number.isInteger(profile.年龄) || profile.年龄 < 18) throw Error('新人物缺少成年年龄');
      seeds[id] = clone(profile); delete seeds[id].档案版本;
    }
    return {commands:[...nativeCommands.filter(c=>c.reason !== 'json_patch'),...commands],seeds};
  }
  const api = {revision:1,prepare};
  if (typeof module !== 'undefined' && module.exports) { module.exports = api; return; }
  const host = window.parent?.document ? window.parent : window;
  (async()=>{
    await waitGlobalInitialized('Mvu');
    host.__xhcsPatchGuardV1?.dispose?.();
    const listener = eventOn(window.Mvu.events.COMMAND_PARSED,(variables,commands,message)=>{
      try {
        const result = prepare(variables.stat_data,commands,message);
        if (!result) return;
        variables.stat_data.重要人物 ??= {};
        Object.assign(variables.stat_data.重要人物,result.seeds);
        commands.splice(0,commands.length,...result.commands);
      } catch (error) {
        commands.splice(0,commands.length);
        console.warn('[香火成神] 本轮状态未同步：'+error.message);
        host.toastr?.error('本轮状态未同步，请检查变量补丁；旧状态已保留。','香火成神系统');
      }
    });
    const controller = {...api,dispose:()=>{listener.stop();if(host.__xhcsPatchGuardV1===controller)delete host.__xhcsPatchGuardV1;}};
    host.__xhcsPatchGuardV1 = controller;
    window.addEventListener('pagehide',controller.dispose,{once:true});
  })().catch(error=>console.error('[香火成神] 状态补丁校验器未就绪',error));
})();
"},{"id":"clock","code":"return (async () => {
  'use strict';
  const parseEpoch = value => {
    if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$/.test(value))return NaN;
    const ms=Date.parse(value.replace(' ','T')+':00Z');
    return Number.isFinite(ms)&&new Date(ms).toISOString().slice(0,16).replace('T',' ')===value?ms:NaN;
  };
  const integer = value => Number.isSafeInteger(value)&&value>=0;
  const stamp = ms => new Date(ms).toISOString().slice(0,16).replace('T',' ');
  const settle = (variables,beforeVariables) => {
    const data=variables?.stat_data, before=beforeVariables?.stat_data;
    if(!data?.元数据?.开局完成 || !data.时序)return;
    const clock=data.时序, old=before?.时序;
    // The model owns elapsed minutes only. Ledger cursor and receipts are script-owned.
    const defaults={古代修仙:'0102-09-16 17:40',异能都市:'2026-07-18 22:10',西幻:'1206-04-03 06:30'};
    const epoch=old?.已初始化?old.起始时刻:before?.元数据?.开局完成?defaults[data.世界?.当前世界]:clock.起始时刻;
    const base=parseEpoch(epoch);
    if(!Number.isFinite(base)||!integer(clock.经过分钟))return;
    const elapsed=Math.max(clock.经过分钟, integer(old?.经过分钟)?old.经过分钟:0);
    if(elapsed>525960000)throw Error('剧情时间超出支持范围');
    const end=base+elapsed*60000;
    const currentDay=Math.floor(end/86400000)-Math.floor(base/86400000);
    const cursor=old?.已初始化&&integer(old.已结算日)?old.已结算日:currentDay;
    const batch=`${epoch}|${cursor}>${currentDay}|${old?.经过分钟??0}>${elapsed}`;
    if(clock.最近批次===batch&&clock.已结算日===currentDay)return;
    const days=Math.max(0,currentDay-cursor);
    const faith=before?.信仰||data.信仰||{};
    const n=v=>Number.isSafeInteger(v)&&v>=0?v:0;
    const rate=n(faith.普通信徒)+5*n(faith.核心信徒)+20*n(faith.狂热信徒);
    const gain=days*rate;
    if(!Number.isSafeInteger(gain)||!Number.isSafeInteger(data.神格?.神力积分))throw Error('香火结算数值无效');
    clock.起始时刻=epoch;clock.经过分钟=elapsed;clock.已初始化=true;
    clock.已结算日=Math.max(cursor,currentDay);clock.最近批次=batch;
    clock.累计香火=n(old?.累计香火)+gain;
    clock.结算记录=Array.isArray(old?.结算记录)?old.结算记录.slice(-7):[];
    if(days){
      data.神格.神力积分+=gain;
      clock.结算记录.push({截止日期:stamp(end).slice(0,10),天数:days,日收益:rate,总额:gain});
      data.信仰.上次结算天数=currentDay+1;
    }
    data.世界.剧情时间=stamp(end);
  };
  const bind = async () => {
    await waitGlobalInitialized('Mvu');
    const listeners=[eventOn(window.Mvu.events.VARIABLE_UPDATE_ENDED,settle)];
    window.addEventListener('pagehide',()=>listeners.forEach(x=>x.stop()),{once:true});
  };
  await bind();
})();
"},{"id":"world-selection","code":"return (async () => {
