    "[种族] 西元大陆·暗精灵",
    "[种族] 西元大陆·兽人",
    "[种族] 西元大陆·矮人",
    "[开局] 西幻·古誓墩晨光",
    "[人物] 西幻·主要女性与相处骨架"
  ]
};
  const owned=new Set(Object.values(groups).flat());
  const identity=()=>{const c=host.SillyTavern?.getContext?.();return `${c?.characters?.[c.characterId]?.avatar||''}:${c?.chatId||''}`;};
  const selected=()=>{
    const c=host.SillyTavern?.getContext?.();
    for(let id=(c?.chat?.length||0)-1;id>=0;id--){
      if(c.chat[id]?.is_user||c.chat[id]?.is_system)continue;
      const variables=window.Mvu?.getMvuData?.({type:'message',message_id:id})||getVariables({type:'message',message_id:id});
      const data=variables?.stat_data;
      if(data?.元数据?.开局完成&&groups[data?.世界?.当前世界])return data.世界.当前世界;
    }
    const draft=getVariables({type:'chat'})?.xhcs_opening_draft_v1;
    return groups[draft?.worldKey]?draft.worldKey:'';
  };
  let queue=Promise.resolve();
  const sync=(world=selected(),expected=identity())=>{
    const operation=async()=>{
      if(identity()!==expected)return {stale:true};
      const book=host.__xhcsRuntimeV1?.worldbook?.()||getCharWorldbookNames('current')?.primary;
      if(!book)throw Error('请先导入并绑定角色卡的内嵌世界书');
      const entries=await getWorldbook(book);
      if(identity()!==expected)return {stale:true};
      if(!entries.some(e=>e.name==='[initvar] 香火成神系统初始状态'||e.extra?.xhcs_project==='xianghuo-cheng-shen'))throw Error('当前绑定的不是本卡世界书');
      const enabled=new Set(groups[world]||[]);
      const required=groups[world]||[];
      if(required.some(name=>!entries.some(e=>e.name===name)))throw Error('世界书版本较旧，请重新导入新版内嵌世界书');
      const mismatch=entries.some(e=>owned.has(e.name)&&e.enabled!==enabled.has(e.name));
      if(mismatch)await updateWorldbookWith(book,list=>{
        if(identity()!==expected)throw Error('聊天已切换，本次世界书选择未保存');
        return list.map(e=>owned.has(e.name)?{...e,enabled:enabled.has(e.name)}:e);
      },{render:'immediate'});
      return {book,world,enabled:[...enabled]};
    };
    queue=queue.catch(()=>{}).then(operation);return queue;
  };
  const api={sync,identity,selected};host.__xhcsWorldbookV7=api;
  const disposers=[];
  const bind=()=>{
    const events=window.tavern_events||{};
    if(typeof eventOn==='function'){
      for(const key of ['CHAT_CHANGED','CHARACTER_MESSAGE_RENDERED','GENERATION_AFTER_COMMANDS']){
        if(events[key])disposers.push(eventOn(events[key],()=>sync().catch(error=>console.warn('[香火成神] 世界书同步：',error.message))));
      }
    }
    void sync().catch(()=>{});
  };
  bind();
  window.addEventListener('pagehide',()=>{disposers.forEach(d=>d.stop());if(host.__xhcsWorldbookV7===api)delete host.__xhcsWorldbookV7;},{once:true});
})();
"},{"id":"hidden-clues","code":"return (async () => {
  'use strict';

  const STAGE_ORDER = {
    泥像期: 0,
    石像期: 1,
    铜像期: 2,
    银像期: 3,
    金像期: 4,
    玉像期: 5,
    宇宙神像期: 6,
  };

  const ENCODED_CLUES = [
    '',
    '',
    '',
    '',
    '',
    '',
  ];

  const decode = value => {
    const bytes = Uint8Array.from(atob(value), char => char.charCodeAt(0));
    return JSON.parse(new TextDecoder('utf-8').decode(bytes));
  };

  const clues = ENCODED_CLUES.map(decode);
  const CHAT_LAST_STAGE_KEY = 'xhcs_clue_last_stage_v1';
  const CHAT_PENDING_CLUE_KEY = 'xhcs_clue_pending_v1';
  let mvu = null;

  const buildInjection = (data, clue) => {
    const persona = String(data?.系统?.人格 || '可靠执事');
    return `【晋升线索·仅本轮可见】
系统人格：${persona}
当前神像阶段：${clue.阶段}
允许透露的线索：
${clue.线索}

本轮要求：
1. 在正文中以“香火成神系统”的口吻简短呈现这条线索，不添加超出这段内容的创世真相。
2. 保持人格声线，体现系统的人味与记忆错位。
3. 在本轮 <UpdateVariable> 中加入：
   - replace /真相/认知阶段 为“${clue.认知阶段}”
   - 如果 /真相/记忆碎片 中没有“${clue.碎片}”，add 到 /真相/记忆碎片/-
   - replace /系统/当前提示 为一句对下一幕有用的系统提示
4. 不要提前透露更高阶段线索。`;
  };

  const getChatVars = () => {
    try {
      return getVariables({ type: 'chat' }) || {};
    } catch (error) {
      console.warn('[香火成神] 晋升线索无法读取聊天变量', error);
      return {};
    }
  };

  const saveChatVars = vars => {
    try {
      replaceVariables(vars, { type: 'chat' });
      const save = window.SillyTavern?.getContext?.()?.saveMetadata?.();
      if (save && typeof save.catch === 'function') {
        save.catch(error => console.warn('[香火成神] 晋升线索聊天变量保存失败', error));
      }
    } catch (error) {
      console.warn('[香火成神] 晋升线索无法写入聊天变量', error);
    }
  };

  const currentData = () => {
    try {
      return mvu?.getMvuData?.({ type: 'message', message_id: 'latest' })?.stat_data || null;
    } catch (_) {
      return null;
    }
  };

  const syncStageAndQueueClue = variables => {
    try {
      const data = variables?.stat_data || variables || currentData();
      if (!data) return;
      const stage = String(data?.神格?.神像阶段 || '泥像期');
      const rank = STAGE_ORDER[stage] ?? 0;
      const vars = getChatVars();
      const storedLastRank = Number(vars[CHAT_LAST_STAGE_KEY]);
      if (!Number.isFinite(storedLastRank)) {
        vars[CHAT_LAST_STAGE_KEY] = rank;
        saveChatVars(vars);
        return;
      }

      if (rank > storedLastRank) {
        vars[CHAT_PENDING_CLUE_KEY] = String(Math.min(rank, clues.length));
        vars[CHAT_LAST_STAGE_KEY] = rank;
        saveChatVars(vars);
      } else if (rank < storedLastRank) {
        vars[CHAT_LAST_STAGE_KEY] = rank;
        saveChatVars(vars);
      }
    } catch (error) {
      console.warn('[香火成神] 晋升阶段同步失败', error);
    }
  };

  const injectPendingClue = () => {
    if ((window.parent||window).__xhcsExtractionDepth>0) return;
    if (!mvu?.getMvuData || typeof injectPrompts !== 'function') return;
    try {
      const data = currentData();
      if (!data) return;
      syncStageAndQueueClue(data);
      const vars = getChatVars();
      const pending = Number(vars[CHAT_PENDING_CLUE_KEY] || 0);
      if (!Number.isInteger(pending) || pending < 1 || pending > clues.length) return;
      const clue = clues[pending - 1];
      injectPrompts([{
        id: `xhcs-promotion-clue-${pending}`,
        position: 'in_chat',
        depth: 0,
        role: 'system',
        content: buildInjection(data, clue),
        should_scan: false,
      }], { once: true });
    } catch (error) {
      console.warn('[香火成神] 晋升线索注入失败', error);
    }
  };

  const clearPendingIfRevealed = () => {
    setTimeout(() => {
      try {
        const data = currentData();
        const vars = getChatVars();
        const pending = Number(vars[CHAT_PENDING_CLUE_KEY] || 0);
        if (!pending || pending < 1 || pending > clues.length) return;
        const fragments = Array.isArray(data?.真相?.记忆碎片) ? data.真相.记忆碎片 : [];
        if (!fragments.includes(clues[pending - 1].碎片)) return;
        vars[CHAT_PENDING_CLUE_KEY] = '';
        saveChatVars(vars);
      } catch (error) {
        console.warn('[香火成神] 晋升线索清理检查失败', error);
      }
    }, 900);
  };

  await (async () => {
    try {
      if (typeof waitGlobalInitialized === 'function') {
        await waitGlobalInitialized('Mvu');
        mvu = window.Mvu;
      } else {
        const startedAt = Date.now();
        while (!window.Mvu && Date.now() - startedAt < 10000) {
          await new Promise(resolve => setTimeout(resolve, 100));
        }
        mvu = window.Mvu;
      }
      if (!mvu) throw new Error('MVU 未就绪');
      if (typeof eventOn !== 'function') return;
      const tavernEvents = window.tavern_events
        || (typeof tavern_events !== 'undefined' ? tavern_events : {});
      const generationAfterCommands = tavernEvents.GENERATION_AFTER_COMMANDS
        || 'GENERATION_AFTER_COMMANDS';
      const generationEnded = tavernEvents.GENERATION_ENDED || 'generation_ended';
      eventOn(generationAfterCommands, injectPendingClue);
      eventOn(generationEnded, clearPendingIfRevealed);
      if (mvu.events?.VARIABLE_UPDATE_ENDED) {
        eventOn(mvu.events.VARIABLE_UPDATE_ENDED, variables => syncStageAndQueueClue(variables));
      }
      if (mvu.events?.VARIABLE_INITIALIZED) {
        eventOn(mvu.events.VARIABLE_INITIALIZED, variables => syncStageAndQueueClue(variables));
      }
      console.info('[香火成神] 晋升线索系统已就绪');
    } catch (error) {
      console.warn('[香火成神] 晋升线索系统初始化失败', error); throw error;
    }
  })();
})();
