          padding: 18px 16px 16px;
        }
        .xhcs-world-grid,
        .xhcs-open-fields,
        .xhcs-persona-grid,
        .xhcs-open-preview {
          grid-template-columns: 1fr;
        }
        .xhcs-open-field[data-span="2"],
        .xhcs-preview-item[data-span="2"] {
          grid-column: auto;
        }
        .xhcs-world-choice {
          min-height: 112px;
        }
        .xhcs-open-foot {
          grid-template-columns: 1fr 1fr;
          padding: 14px 16px 18px;
        }
        .xhcs-open-status {
          grid-column: 1 / -1;
          grid-row: 1;
          text-align: left;
        }
      }
      .xhcs-open-tools{display:flex;flex-direction:column;align-items:flex-end;gap:8px}
      .xhcs-open-settings{font:inherit;color:var(--xhcs-paper);background:var(--xhcs-ink-2);border:1px solid var(--xhcs-gold);border-radius:7px;min-height:40px;padding:6px 14px;cursor:pointer}
      @media(max-width:600px){.xhcs-open-tools{grid-column:2;align-items:flex-start;flex-direction:row;flex-wrap:wrap;align-items:center}}
      @media (prefers-reduced-motion: reduce) {
        .xhcs-world-choice {
          transition: none;
        }
      }
    `;
    hostDocument.head.appendChild(style);
  };

  const shellTemplate = () => `
    <div class="xhcs-opening">
      <div class="xhcs-open-shell" data-view="form">
        <header class="xhcs-open-head">
          <div class="xhcs-open-sigil" aria-hidden="true">神</div>
          <div>
            <p class="xhcs-open-kicker">香火成神系统</p>
            <h2 class="xhcs-open-title">建立第一座神座</h2>
          </div>
          <div class="xhcs-open-tools"><button type="button" class="xhcs-open-settings" data-action="settings" aria-label="打开设置">设置</button><span class="xhcs-open-step-chip" data-step-chip>一 / 三</span></div>
        </header>
