  const number = value => {
    if (value === null || value === undefined || value === '' || typeof value === 'boolean') return NaN;
    const parsed = Number(value);
    return Number.isFinite(parsed) && parsed >= 0 ? parsed : NaN;
  };

  const text = value => {
    if (value === null || value === undefined) return '';
