    const faith = data?.信仰 || {};
    const total = number(faith.普通信徒) + number(faith.核心信徒) + number(faith.狂热信徒);
    const rules = {
      泥像期: { stage: '石像期', total: 0, core: 1, fanatic: 0, note: '首位核心信徒自愿立誓' },
      石像期: { stage: '铜像期', total: 10, core: 3, fanatic: 0, note: '完成公开神迹或建立祭祀点' },
