  const cleanScene = message => String(message||'')
    .replace(/<UpdateVariable>[\s\S]*?(?:<\/UpdateVariable>|$)/gi,'')
    .replace(/<CharacterArchive>[\s\S]*?(?:<\/CharacterArchive>|$)/gi,'')
    .replace(/<thinking>[\s\S]*?(?:<\/thinking>|$)/gi,'')
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,'')
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi,'')
    .replace(/<[^>]+>/g,'').trim();
  const collectCharacterScenes=(name,aliases=[])=>{
    const rows=getChatMessages('0-{{lastMessageId}}',{role:'all',hide_state:'unhidden',include_swipes:true});
    const hits=[];const names=[name,...aliases].filter(Boolean);
    const sd=typeof window!=='undefined'&&typeof latestAssistantMessage==='function'?window.Mvu?.getMvuData?.({type:'message',message_id:latestAssistantMessage()?.message_id})?.stat_data:null;
    const personKey=Object.entries(sd?.重要人物||{}).find(([,p])=>p.姓名===name)?.[0];
    const present=(sd?.剧情?.在场人物||[]).includes(personKey);
    rows.forEach((row,index)=>{
      const scene=cleanScene(row.message ?? row.swipes?.[row.swipe_id??0]);
      if(!name||(!names.some(n=>scene.includes(n))&&!(present&&index>=rows.length-2))||scene.includes('【开局设定】'))return;
      const paragraphs=scene.split(/\n\s*\n/),indexes=new Set();
      paragraphs.forEach((p,i)=>{if(names.some(n=>p.includes(n)))for(const near of [i-1,i,i+1])if(near>=0&&near<paragraphs.length)indexes.add(near);});
      const excerpt=([...indexes].sort((a,b)=>a-b).map(i=>paragraphs[i]).join('\n\n')||scene).slice(0,1800);
      hits.push({floor:row.message_id,swipe:row.swipe_id??0,role:row.role,text:excerpt});
    });
    const chosen=hits.length<=36?hits:[...hits.slice(0,6),...hits.slice(-30)];
    return {scenes:chosen,total:hits.length};
  };
  const distillCharacter=async(person,key)=>{
