    if(typeof generateRaw!=='function'){status.textContent='酒馆助手生成接口不可用，请检查角色脚本权限。';return;}
    const publicKeys=new Set(['姓名','年龄','性别','身份','信仰等级','关系','所在位置','所在地','当前状态','情绪','外貌','能力','与神关系','近期经历','别称','情感关系','背景','性格','说话方式','目标','认知边界','成长','扮演摘要','归档正文','旧归档正文']);
